#include "ksControllerBoundary.h"
#include <stdexcept>
namespace ks{namespace{PanelDecimalPartialTest partialTest=nullptr;using T=PanelDecimalTask;using S=T::Stage;struct Point{unsigned location,length;};Point point(S s){switch(s){case S::BindBuffer:return{0xa94,6};case S::WritePadding:return{0xa9a,2};case S::NextPosition:return{0xa9c,2};case S::DecreaseWidth:return{0xa9e,2};case S::AdmitPadding:return{0xaa0,2};case S::SetEnd:return{0xaa2,2};case S::WriteEnd:return{0xaa4,2};case S::SetBase:return{0xaa6,2};case S::ClearRemainder:return{0xaa8,2};case S::Divide:return{0xaaa,2};case S::EncodeDigit:return{0xaac,2};case S::PreviousPosition:return{0xaae,2};case S::WriteDigit:return{0xab0,2};case S::TestRemaining:return{0xab2,2};case S::AdmitDigits:return{0xab4,2};case S::Finish:return{0xab6,2}; default:throw std::runtime_error("Invalid panel decimal stage");}}}
bool PanelDecimalCalls::step(ControllerCpu&h){using namespace controllerDetail;unsigned pc=unsigned(h.getPC());std::optional<Call>*selected=nullptr;for(auto&c:calls)if(c&&c->token==h.getSP()){selected=&c;break;}if(pc==0xa94){if(selected)throw std::runtime_error("Overlapping panel decimal");for(auto&c:calls)if(!c){selected=&c;break;}if(!selected)throw std::runtime_error("Panel decimal capacity");selected->emplace(h.getSP());++started;}if(!selected||point((**selected).task.stage()).location!=pc){if(partialTest&&partialTest(h)){++partialEntries;return true;}return false;}auto&t=(**selected).task;auto stage=t.stage();auto before=h.cycles;Boundary f(h,pc,point(stage).length);auto&v=h.regs;auto cost=t.nextClocks();t.advanceBefore(cost,[&](T::Read r){return r==T::Read::Padding?uint8_t(v[2].rl):r==T::Read::Width?uint8_t(v[2].rh):uint8_t(v[0].rl);},[&](int32_t pos,uint8_t value){f.store8(uint32_t(0xffec34+pos)&0xffffff,int8_t(value));});switch(stage){case S::BindBuffer:f.move(v[1].er,0xffec34);break;case S::NextPosition:f.inc(v[1].er,1);break;case S::DecreaseWidth:f.inc(v[2].rh,-1);break;case S::SetEnd:f.move(v[2].rl,0);break;case S::SetBase:f.move(v[2].rl,10);break;case S::ClearRemainder:v[0].rh=h.sub8(v[0].rh,v[0].rh);break;case S::Divide:flag(h,8,false);flag(h,4,false);v[0].r=int16_t(unsigned(t.remainder())<<8|t.value());h.clockI(12);break;case S::EncodeDigit:v[0].rh=h.add8(v[0].rh,0x30);break;case S::PreviousPosition:f.inc(v[1].er,-1);break;case S::TestRemaining:f.move(v[0].rl,v[0].rl);break;case S::Finish:f.ret();h.pc=h.makepc(f.next);selected->reset();++completed;break;default:break;}if(stage!=S::Finish)h.pc=h.makepc(point(t.stage()).location);if(h.cycles-before!=cost)throw std::runtime_error("Panel decimal clocks differ");return true;}}

